mapper.select:
select
    t1.*
from deduction_item_period t1
inner join (
    select
        coupon_id, max(crt_time) as max_crt_time
    from deduction_item_period
    where coupon_id in

            #{item}

        and crt_time <= #{date}
    group by coupon_id
    ) t2 on t1.coupon_id = t2.coupon_id and t1.crt_time = t2.max_crt_time;
